import math
max_lr, min_lr, warm, max_steps = 6e-4, 6e-5, 715, 19073
def lr(it):
    if it < warm:
        return max_lr * (it + 1) / warm
    if it > max_steps:
        return min_lr
    r = (it - warm) / (max_steps - warm)
    return min_lr + 0.5 * (1 + math.cos(math.pi * r)) * (max_lr - min_lr)
print(lr(0), lr(714), lr(9894), lr(19072))   # about 8.4e-07, 6e-04, 3.3e-04, 6e-05
```
